def describe_digital_civilization_intelligence() -> str:
    lines = [
        "TitanAI Autonomous Digital Civilization Era",
        "",
        "This layer frames TitanAI as a full intelligence operating ecosystem for platforms, workforces, innovation, data, decision, customer, security, knowledge, interaction, operations, and marketplaces.",
        "",
    ]
    for capability in DIGITAL_CIVILIZATION_CAPABILITIES:
        lines.append(f"- {capability.version} {capability.name} [{capability.category}]")
        lines.append(f"  {capability.purpose}")
    return "\n".join(lines)
